<?php
namespace App\Http\Controllers;
use App\Models\EmployeeContract; use App\Models\LocumSession; use App\Services\WorkforceAuditService; use Illuminate\Http\Request;
class LocumSessionController extends Controller { public function index(){ $sessions=LocumSession::query()->latest('session_date')->paginate(30); return view('workforce.locum.index',compact('sessions')); }
public function store(Request $r, WorkforceAuditService $audit){$d=$r->validate(['employee_id'=>'required|exists:employees,id','contract_id'=>'nullable|exists:employee_contracts,id','unit_id'=>'required|exists:units,id','cost_centre_id'=>'nullable|exists:cost_centres,id','session_date'=>'required|date','start_time'=>'required','end_time'=>'required','patients_seen'=>'nullable|integer|min:0','revenue_amount'=>'nullable|numeric|min:0','calculation_method'=>'required|in:session,hourly,per_patient,revenue_share,hybrid']);$contract=$d['contract_id']?EmployeeContract::find($d['contract_id']):EmployeeContract::where('employee_id',$d['employee_id'])->where('is_active',true)->latest('start_date')->first();$hours=max(0,(strtotime($d['end_time'])-strtotime($d['start_time']))/3600);$amount=match($d['calculation_method']){'hourly'=>$hours*(float)($contract->hourly_rate??0),'per_patient'=>(int)($d['patients_seen']??0)*(float)($contract->patient_rate??0),'revenue_share'=>(float)($d['revenue_amount']??0)*(float)($contract->revenue_share_percent??0)/100,'hybrid'=>(float)($contract->session_rate??0)+(float)($d['revenue_amount']??0)*(float)($contract->revenue_share_percent??0)/100,default=>(float)($contract->session_rate??0)};$d['calculated_amount']=$amount;$d['recorded_by']=auth()->id();$m=LocumSession::create($d);$audit->model('created',$m,'Locum/session duty recorded');return back()->with('success','Session recorded.');}}